const money=v=>Number.isFinite(Number(v))?Number(v).toLocaleString("id-ID",{maximumFractionDigits:2}):"—";
const pct=v=>{const n=Number(v);return Number.isFinite(n)?(n*100).toFixed(1)+"%":"—"};
const safe=v=>(v===null||v===undefined||v==="")?"—":String(v);
const statusClass=v=>String(v||"").toLowerCase().replace(/\s+/g,"-");
const EXCEPTIONS=new Set(["Warning","Breach","Data Issue"]);
function StatusBadge({value}){return <span className={"pf-status-badge "+statusClass(value)}>{safe(value)}</span>}
function GridPager({page,pageCount,pageSize,setPage,setPageSize,total}){return <div className="pf-grid-pager"><span>{total.toLocaleString("id-ID")} records · Page {page} of {pageCount}</span><div><select value={pageSize} onChange={e=>{setPageSize(Number(e.target.value));setPage(1)}}><option value="25">25 / page</option><option value="50">50 / page</option><option value="100">100 / page</option></select><button disabled={page<=1} onClick={()=>setPage(p=>Math.max(1,p-1))}>Previous</button><button disabled={page>=pageCount} onClick={()=>setPage(p=>Math.min(pageCount,p+1))}>Next</button></div></div>}
function UniversePath({universe,compact=false}){const path=PRODUCT_FINAL_DIMENSION_CONTRACT[universe]?.path||[];return <div className={"pf-universe-path"+(compact?" compact":"")}>{path.map((x,i)=><React.Fragment key={x}><span>{x}</span>{i<path.length-1?<b>→</b>:null}</React.Fragment>)}</div>}
function AllocationTable({universe,allocation=[]}){if(!allocation.length)return <div className="pf-empty-state"><strong>No utilization components</strong><span>The current canonical snapshot does not expose an allocation row for this object.</span></div>;return <div className="pf-table-wrap"><table className="pf-table pf-drilldown-table"><thead><tr><th>Product / Component</th>{universe==="Country"?<><th>Domestic</th><th>Overseas</th><th>Total</th></>:<th>Exposure</th>}</tr></thead><tbody>{allocation.map((x,i)=><tr key={(x.product||"component")+"|"+i}><td className="pf-cell-wrap">{safe(x.product)}</td>{universe==="Country"?<><td>{money(x.domestic)}</td><td>{money(x.overseas)}</td><td>{money(x.total)}</td></>:<td>{money(x.exposure)}</td>}</tr>)}</tbody></table></div>}
function MonitoringDetail({universe,row,structureRow,detailRow,onClose}){return <aside className="pf-drawer pf-detail-drawer" aria-label="Utilization drill down"><div className="pf-drawer-head"><div><div className="pf-label">{universe} · UTILIZATION DETAIL</div><h3>{safe(row?.name||row?.key)}</h3><p>{safe(row?.key)}</p></div><button className="pf-drawer-close" onClick={onClose}>Close</button></div><div className="pf-detail-callout"><strong>{PRODUCT_FINAL_DIMENSION_CONTRACT[universe]?.detailTitle||"Utilization Trace"}</strong><span>Read-only trace from canonical monitoring/master snapshots.</span></div><div className="pf-section-heading">Analytical Path</div><UniversePath universe={universe}/><div className="pf-detail-kpis"><div><span>Master Limit</span><strong>{money(structureRow?.limit??row?.limit)}</strong></div><div><span>Exposure</span><strong>{money(structureRow?.exposure??row?.exposure)}</strong></div><div><span>Available</span><strong>{money(structureRow?.available??((Number(row?.limit)||0)-(Number(row?.exposure)||0)))}</strong></div><div><span>Utilization</span><strong>{pct(structureRow?.utilization??row?.utilization)}</strong></div></div><div className="pf-detail-dimensions">{universe==="Country"?<><div><span>Country Code</span><strong>{safe(row?.countryCode||row?.key)}</strong></div><div><span>Domestic Capacity</span><strong>{money(row?.domesticCapacity)}</strong></div><div><span>Overseas Capacity</span><strong>{money(row?.overseasCapacity)}</strong></div></>:null}{universe==="CCL"?<><div><span>Counterparty</span><strong>{safe(row?.name)}</strong></div><div><span>Country</span><strong>{safe(row?.country)}</strong></div><div><span>Category</span><strong>{safe(row?.category)}</strong></div><div><span>Contractual</span><strong>{money(row?.contractual)}</strong></div></>:null}{universe==="MLK"?<><div><span>Group</span><strong>{safe(row?.group)}</strong></div><div><span>Entity</span><strong>{safe(row?.entity)}</strong></div><div><span>BMPK Entitas</span><strong>{money(row?.bmpkEntitas)}</strong></div></>:null}{universe==="CIL"?<><div><span>Insurance</span><strong>{safe(row?.insurance||row?.key)}</strong></div><div><span>Entity</span><strong>{safe(row?.entity)}</strong></div></>:null}{universe==="LPG"?<><div><span>Ecosystem / Sector</span><strong>{safe(row?.sector)}</strong></div><div><span>Segment</span><strong>{safe(row?.segment)}</strong></div><div><span>Region</span><strong>{safe(row?.region)}</strong></div></>:null}</div><div className="pf-section-heading">Underlying Utilization</div><AllocationTable universe={universe} allocation={structureRow?.allocation||[]}/><div className="pf-section-heading">Product Contribution</div><div className="pf-product-contribution">{safe(row?.productContribution)}</div>{detailRow?.sections?<details className="pf-master-detail-accordion"><summary>View canonical master fields</summary><div className="pf-master-sections compact">{Object.entries(detailRow.sections).map(([section,fields])=><section className="pf-master-section" key={section}><div className="pf-section-heading">{section}</div><div className="pf-master-fields">{fields.slice(0,30).map((f,i)=><div className="pf-master-field" key={f.field+"|"+i}><span>{f.field}</span><strong>{safe(f.value)}</strong></div>)}</div></section>)}</div></details>:null}</aside>}
function MonitoringView({adapter,onNavigate,initialUniverse}){const [universe,setUniverse]=useState(PRODUCT_FINAL_UNIVERSES.includes(initialUniverse)?initialUniverse:"Country"),[status,setStatus]=useState("All"),[query,setQuery]=useState(""),[selected,setSelected]=useState(null),[page,setPage]=useState(1),[pageSize,setPageSize]=useState(25),[sortKey,setSortKey]=useState("utilization"),[sortDir,setSortDir]=useState("desc");const snapshots=useMemo(()=>Object.fromEntries(PRODUCT_FINAL_UNIVERSES.map(x=>[x,adapter.getMonitoringSnapshot(x)])),[adapter]);const structures=useMemo(()=>Object.fromEntries(adapter.getLimitStructureSnapshot().map(x=>[x.type,x])),[adapter]);const details=useMemo(()=>Object.fromEntries(adapter.getMasterLimitDetailsSnapshot().map(x=>[x.type,x])),[adapter]);const snapshot=snapshots[universe],rows=snapshot?.rows||[],contract=PRODUCT_FINAL_DIMENSION_CONTRACT[universe];const filtered=rows.filter(r=>(status==="All"||r.status===status)&&Object.values(r||{}).join(" ").toLowerCase().includes(query.trim().toLowerCase()));const sorted=[...filtered].sort((a,b)=>{const an=Number(a?.[sortKey]),bn=Number(b?.[sortKey]);const c=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:String(a?.[sortKey]??"").localeCompare(String(b?.[sortKey]??""),"id",{numeric:true,sensitivity:"base"});return c*(sortDir==="asc"?1:-1)});const pageCount=Math.max(1,Math.ceil(sorted.length/pageSize)),safePage=Math.min(page,pageCount),pageRows=sorted.slice((safePage-1)*pageSize,safePage*pageSize),structureRows=structures[universe]?.rows||[],detailRows=details[universe]?.rows||[],selectedStructure=selected?structureRows.find(x=>String(x.key)===String(selected.key)):null,selectedDetail=selected?detailRows.find(x=>String(x.key)===String(selected.key)):null;const headers={Country:[["Code","countryCode"],["Country","name"],["Limit","limit"],["Exposure","exposure"],["Utilization","utilization"],["Status","status"]],CCL:[["Swift","key"],["Bank","name"],["Country","country"],["Contractual","contractual"],["Outstanding","exposure"],["Utilization","utilization"],["Status","status"]],MLK:[["CIF","key"],["Debtor","name"],["Group","group"],["Entity","entity"],["Limit","limit"],["Exposure","exposure"],["Utilization","utilization"],["Status","status"]],CIL:[["Insurance","insurance"],["Name","name"],["Entity","entity"],["CIL","limit"],["Exposure","exposure"],["Utilization","utilization"],["Status","status"]],LPG:[["Sector","sector"],["Segment","segment"],["Region","region"],["Limit","limit"],["Outstanding","exposure"],["Utilization","utilization"],["Status","status"]]}[universe];const toggle=k=>{if(sortKey===k)setSortDir(x=>x==="asc"?"desc":"asc");else{setSortKey(k);setSortDir("desc")}setPage(1)};return <div><section className="pf-page-intro pf-card"><div><div className="pf-label">OPERATIONAL MONITORING</div><h2>{universe}</h2><p>{contract?.notes}</p></div><div className="pf-page-intro-right"><span className="pf-readonly-badge">{rows.length.toLocaleString("id-ID")} OBJECTS</span><span className="pf-readonly-badge">CANONICAL</span></div></section><div className="pf-monitor-tabs">{PRODUCT_FINAL_UNIVERSES.map(x=><button key={x} className={universe===x?"active":""} onClick={()=>{setUniverse(x);setSelected(null);setPage(1)}}>{x}</button>)}</div><div className="pf-path-strip"><UniversePath universe={universe} compact/><button className="pf-button-secondary" onClick={()=>onNavigate("limits",universe)}>Open Limit Structure</button></div>{!snapshot?<div className="pf-placeholder"><strong>Monitoring snapshot unavailable</strong></div>:<section className="pf-card"><div className="pf-monitor-summary"><div><span>Limit</span><strong>{money(snapshot.totalLimit)}</strong></div><div><span>Exposure</span><strong>{money(snapshot.totalExposure)}</strong></div><div><span>Utilization</span><strong>{pct(snapshot.utilization)}</strong></div><div><span>Exceptions</span><strong>{(snapshot.statusCounts?.Warning||0)+(snapshot.statusCounts?.Breach||0)+(snapshot.statusCounts?.["Data Issue"]||0)}</strong></div></div><div className="pf-monitor-toolbar"><select value={status} onChange={e=>{setStatus(e.target.value);setPage(1)}}><option>All</option><option>Normal</option><option>Warning</option><option>Breach</option><option>Data Issue</option></select><input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Search all dimensions..."/><span className="pf-monitor-count">{filtered.length.toLocaleString("id-ID")} / {rows.length.toLocaleString("id-ID")}</span></div><div className="pf-table-wrap"><table className="pf-table"><thead><tr>{headers.map(([label,key])=><th key={key}><button className="pf-th-sort" onClick={()=>toggle(key)}>{label}</button></th>)}<th>Journey</th></tr></thead><tbody>{pageRows.map((row,i)=><tr key={String(row.key)+"|"+i} onClick={()=>setSelected(row)}>{headers.map(([label,key])=><td key={key} className={key==="name"||key==="entity"?"pf-cell-wrap":""}>{key==="status"?<StatusBadge value={row[key]}/>:key==="utilization"?pct(row[key]):["limit","exposure","contractual"].includes(key)?money(row[key]):safe(row[key])}</td>)}<td><button className="pf-row-action" onClick={e=>{e.stopPropagation();setSelected(row)}}>Drill down</button></td></tr>)}</tbody></table></div><GridPager page={safePage} pageCount={pageCount} pageSize={pageSize} setPage={setPage} setPageSize={setPageSize} total={sorted.length}/>{selected?<MonitoringDetail universe={universe} row={selected} structureRow={selectedStructure} detailRow={selectedDetail} onClose={()=>setSelected(null)}/>:null}</section>}</div>}
